import { atom, read, update } from 'claude-code'
import type {
  CommandPresentation,
  EngineInterface,
  PaneOpenArgs,
  Register,
  SessionContextUsage,
  SessionRateLimit,
} from 'claude-code'

import type { AgentView, Board, JournalRow, TeamRow, UsageView } from '../types'

// The pane: one per session, drawn by the ui.render hook below. Its place is the dock
// beside the transcript, which only the fullscreen layout has, from 110 columns.
const PANE = 'team-board'
const OPEN: PaneOpenArgs = { id: PANE, title: 'Teams and usage', columns: 56 }
const DOCK_FLOOR = 110
const REFRESH_MS = 10_000

// The board comes from the repository's own script, run in the main checkout's root.
// The session's working directory can be a subfolder or a worktree that has no .venv.
function script(root: string): string[] {
  return [`${root}/.venv/bin/python`, `${root}/.claude/build-lead/team_status.py`, 'show', '--json']
}

const board = atom({ plugin: 'team-board', key: 'board' } as const, { generatedAt: 0, teams: [] } as Board)
const usage = atom({ plugin: 'team-board', key: 'usage' } as const, { limits: [] } as UsageView)
const agents = atom({ plugin: 'team-board', key: 'agents' } as const, [] as AgentView[])

const LIVE = new Set(['running', 'pending', 'waiting'])
const FINAL = /^(status: (complete|pass)|verdict: (approved|pass))\b/

function toUsage(context: SessionContextUsage, limits: SessionRateLimit[]): UsageView {
  return {
    contextPercent: context.percent,
    contextTokens: context.tokens,
    contextWindow: context.window,
    limits: limits.map(l => ({ kind: l.kind, percentUsed: l.percentUsed, resetsAt: l.resetsAt })),
  }
}

function clockTime(ms: number): string {
  const d = new Date(ms)
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

function untilText(ms: number, now: number): string {
  const minutes = Math.max(0, Math.round((ms - now) / 60_000))
  return minutes >= 60 ? `${Math.floor(minutes / 60)}h ${minutes % 60}m` : `${minutes}m`
}

function journalMark(row: JournalRow): string {
  if (FINAL.test(row.status)) return `${row.role} done`
  if (row.status === '') return `${row.role} ?`
  return `${row.role} ${row.status.replace(/^(status|verdict): /, '')}`
}

function placementText(p: CommandPresentation): string {
  if (!p.isFullscreen) {
    return 'Team board opened above the prompt. The dock beside the transcript needs the fullscreen layout: run /tui fullscreen, which restarts and resumes this session.'
  }
  if (p.columns < DOCK_FLOOR) {
    return `Team board opened above the prompt. The dock beside the transcript needs ${DOCK_FLOOR} columns; the terminal has ${p.columns}.`
  }

  return 'Team board opened in the dock beside the transcript and refreshed.'
}

function stateColor(team: TeamRow): 'success' | 'warning' | 'error' | 'subtle' {
  if (team.state === 'running') return 'warning'
  if (team.state === 'handed off') return 'success'
  if (team.state === 'blocked' || team.state.startsWith('stopped')) return 'error'
  return 'subtle'
}

let isBusy = false
let isOpenedUnasked = false

async function refresh($: EngineInterface): Promise<void> {
  if (isBusy) return
  isBusy = true
  try {
    try {
      const repo = await $.session.repo()
      if (!repo) throw new Error('the session is not in a git repository')
      const ran = await $.process.run(script(repo.root), {
        cwd: repo.root,
        env: { ANTHROPIC_API_KEY: '', GEMINI_API_KEY: '' },
        timeoutMs: 25_000,
      })
      const parsed = ran.exitCode === 0 ? JSON.parse(ran.stdout) : undefined
      const now = await $.clock.now()
      await update($, board, previous =>
        parsed
          ? { generatedAt: now, teams: parsed.teams as TeamRow[] }
          : { ...previous, error: `team_status.py exited ${ran.exitCode}: ${ran.stderr.trim().split('\n').pop() ?? ''}` },
      )
    } catch (error) {
      await update($, board, previous => ({
        ...previous,
        error: `cannot read the board here: ${String(error).slice(0, 120)}`,
      }))
    }
    const measured = await $.session.usage()
    await update($, usage, () => toUsage(measured.context, measured.rateLimits))
    const list = await $.agent.list()
    await update($, agents, () =>
      list.map(a => ({ id: a.id, type: a.type, description: a.description, status: a.status })),
    )
  } finally {
    isBusy = false
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'team-board',
      description: 'Show each worktree team, its step and subagents, and the 5-hour, 7-day and context usage',
    })
    void refresh($)
    $.clock.every(REFRESH_MS, () => void refresh($))

    return next(e)
  })

  on('command.run', { command: 'team-board' }, async ($, e) => {
    await $.ui.open(OPEN)
    await refresh($)

    return { text: placementText(e.presentation) }
  })

  // Only a render says whether the surface docks a pane. Unasked, the pane opens only
  // where it docks: on the main screen it would take the rows above the prompt.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (!isOpenedUnasked && e.viewport?.isFullscreen === true) {
      isOpenedUnasked = true
      void $.ui.open(OPEN)
    }

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await update($, usage, () => toUsage(e.context, e.rateLimits))

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const b = await read($, board)
    const u = await read($, usage)
    const live = (await read($, agents)).filter(a => LIVE.has(a.status))
    const now = b.generatedAt || (await $.clock.now())
    const five = u.limits.find(l => l.kind === 'five_hour')
    const seven = u.limits.find(l => l.kind === 'seven_day')

    return (
      <Box flexDirection="column">
        <Text bold>Teams{b.generatedAt ? <Text dimColor> updated {clockTime(b.generatedAt)}</Text> : ''}</Text>
        {b.error && <Text color="error" wrap="truncate-end">{b.error}</Text>}
        {b.teams.length === 0 && !b.error && <Text dimColor>No registered team run.</Text>}
        {b.teams.map(team => (
          <Box key={`team-${team.team}`} flexDirection="column" marginTop={1}>
            <Text wrap="truncate-end">
              <Text bold>Team {team.team}</Text> {team.unit}
            </Text>
            <Text wrap="truncate-end">
              {'  '}
              <Text color={stateColor(team)}>{team.state}</Text>
              <Text dimColor>
                {' '}· {team.route} {team.model ?? ''} {team.effort ?? ''}
                {team.elapsed ? ` · ${team.elapsed}` : ''}
              </Text>
            </Text>
            {team.state === 'running' && (
              <Text wrap="truncate-end">
                {'  '}step: <Text bold>{team.step}</Text>
              </Text>
            )}
            {team.running_subagents.map((s, i) => (
              <Text key={`sub-${team.team}-${i}`} wrap="truncate-end">
                {'  '}
                <Text color="warning">runs</Text> {s.role}
                <Text dimColor> {s.description}</Text>
              </Text>
            ))}
            {team.journal.length > 0 && (
              <Text dimColor wrap="truncate-end">
                {'  '}
                {team.journal.map(journalMark).join(' · ')}
              </Text>
            )}
            <Text dimColor wrap="truncate-end">
              {'  '}commits {team.commits} · uncommitted {team.uncommitted}
              {team.agy_quota_resets_at
                ? ` · agy quota resets ${clockTime(team.agy_quota_resets_at * 1000)}`
                : ''}
            </Text>
          </Box>
        ))}
        <Text bold>{'\n'}This session's subagents</Text>
        {live.length === 0 && <Text dimColor>none running</Text>}
        {live.map(a => (
          <Text key={`agent-${a.id}`} wrap="truncate-end">
            <Text color="warning">{a.status}</Text> {a.type}
            <Text dimColor> {a.description}</Text>
          </Text>
        ))}
        <Text bold>{'\n'}Usage</Text>
        <Text wrap="truncate-end">
          5h{'  '}
          {five ? `${five.percentUsed}% used` : <Text dimColor>no reading yet</Text>}
          {five?.resetsAt ? (
            <Text dimColor>
              {' '}· resets {clockTime(Date.parse(five.resetsAt))} (in {untilText(Date.parse(five.resetsAt), now)})
            </Text>
          ) : (
            ''
          )}
        </Text>
        <Text wrap="truncate-end">
          7d{'  '}
          {seven ? `${seven.percentUsed}% used` : <Text dimColor>no reading yet</Text>}
          {seven?.resetsAt ? <Text dimColor> · resets {new Date(seven.resetsAt).toDateString()}</Text> : ''}
        </Text>
        <Text wrap="truncate-end">
          ctx {u.contextPercent !== undefined ? `${u.contextPercent}%` : <Text dimColor>no reading yet</Text>}
          {u.contextTokens !== undefined && u.contextWindow ? (
            <Text dimColor>
              {' '}· {Math.round(u.contextTokens / 1000)}k of {Math.round(u.contextWindow / 1000)}k
            </Text>
          ) : (
            ''
          )}
        </Text>
      </Box>
    )
  })
}

