export type JournalRow = { file: string; role: string; status: string }
export type SubagentRow = { role: string; description: string }
export type TeamRow = {
  team: string
  unit: string
  route: string
  model: string | null
  effort: string | null
  state: string
  step: string
  elapsed: string | null
  running_subagents: SubagentRow[]
  subagents_done: number
  journal: JournalRow[]
  commits: number
  uncommitted: number
  agy_quota_resets_at: number | null
}
export type Board = { generatedAt: number; teams: TeamRow[]; error?: string }
export type LimitView = { kind: string; percentUsed: number; resetsAt?: string }
export type UsageView = { contextPercent?: number; contextTokens?: number; contextWindow?: number; limits: LimitView[] }
export type AgentView = { id: string; type: string; description: string; status: string }

declare module 'claude-code' {
  interface PluginState {
    'team-board': { board: Board; usage: UsageView; agents: AgentView[] }
  }
}
